  "assumptions": [
    "Received-at means the time the event store service accepted and durably persisted the record, not any producer-supplied event time.",
    "The event store is a single logical store owned by this service, and no other system holds primary copies of event records.",
    "Producers and consumers can authenticate using the platform's standard service-to-service mechanism."
  ],
  "risks": [
    {
      "detail": "SDLC-FR-0201 and SDLC-FR-0202 directly contradict each other for records aged between seven and ninety days. Until the contradiction is resolved, no implementation can pass both acceptance criteria.",
      "impact": "HIGH"
    },
    {
      "detail": "Storage capacity differs by roughly a factor of thirteen between the two candidate windows. Sizing for the wrong one risks either overspending or running out of capacity.",
      "impact": "MEDIUM"
    },
    {
      "detail": "Copies of records outside the event store, such as caches in consumers or downstream exports, are not covered by in-store deletion. They could undermine the deletion intent even though backups are explicitly excluded.",
      "impact": "MEDIUM"
    }
  ],
  "open_architecture_questions": [
    "What enforcement scheduling interval and partition granularity are acceptable for the gap between logical expiry and physical deletion, once the governing horizon is known?"
  ],
  "product_questions": [
    {
      "detail": "SDLC-FR-0201 requires every event record to be permanently deleted seven days after receipt, while SDLC-FR-0202 requires every event record to remain retrievable for at least ninety days after receipt. Both apply without exception. Which obligation governs, or do the two Requirements apply to different classes of event records that the Requirements do not yet distinguish?",
      "requirement_id": "SDLC-FR-0201",
      "material": true
    },
    {
      "detail": "SDLC-FR-0202 conflicts with SDLC-FR-0201: ninety-day minimum availability versus deletion at seven days, both applied to every event record without exception. Which obligation governs, or how is the scope of each Requirement to be separated?",
      "requirement_id": "SDLC-FR-0202",
      "material": true
    }
  ]
}
